	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("deployed_model"); !tpgresource.IsEmptyValue(reflect.ValueOf(deployedModelProp)) && (ok || !reflect.DeepEqual(v, deployedModelProp)) {
		obj["deployedModel"] = deployedModelProp
	}
